const $=s=>document.querySelector(s),escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art={
fruta:'<ellipse cx="75" cy="111" rx="53" ry="8" fill="#8c7b4722"/><path d="M70 44Q30 29 27 67Q24 105 66 113Q108 114 120 78Q128 40 88 40Z" fill="#b24a32"/><path d="M72 46Q72 24 85 14" stroke="#5b4a28" stroke-width="6" fill="none"/><path d="M79 31Q96 4 116 18Q101 40 79 31" fill="#50734b"/><path d="M47 49Q35 59 40 76" stroke="#e3a16d" stroke-width="6" fill="none" stroke-linecap="round"/>',
pao:'<ellipse cx="75" cy="112" rx="59" ry="8" fill="#8c7b4722"/><path d="M19 91Q22 49 63 32Q102 14 126 48Q151 91 109 109L44 112Q18 108 19 91" fill="#b67c3f"/><path d="M43 59L66 79M65 43L89 62M89 34L111 51" stroke="#f1d09a" stroke-width="10" stroke-linecap="round"/><path d="M31 95Q65 108 117 89" stroke="#8a562b" stroke-width="3" fill="none"/>',
mercearia:'<path d="M35 27H111L117 116H28Z" fill="#d6c097"/><path d="M35 27L28 14H104L111 27" fill="#b69e77"/><path d="M47 54H101V91H47Z" fill="#f7f4eb"/><path d="M72 62V84M62 67L72 75L84 65" stroke="#64794e" stroke-width="3" fill="none"/><path d="M43 30L38 110" stroke="#f0dfbd" stroke-width="4"/>',
casa:'<path d="M63 9H88V25H63Z" fill="#556f57"/><path d="M58 24H93L104 47V116H43V47Z" fill="#d3b778"/><path d="M51 58H98V96H51Z" fill="#f2ead6"/><path d="M69 64Q50 86 72 90Q94 85 76 64" fill="#7d9e8a"/><path d="M49 46L59 32" stroke="#f6e4b7" stroke-width="5" stroke-linecap="round"/>'};
const categories=[['Fruta e legumes','Frescos','fruta','Cor e sabor à mesa'],['Pão e pequeno-almoço','Frescos','pao','Para começar o dia'],['Mercearia','Mercearia','mercearia','Os essenciais da despensa'],['Casa e higiene','Casa','casa','Cuidar do que é seu']];
let filter='Todas',list=[];try{list=JSON.parse(localStorage.getItem('delmar-list')||'[]').filter(x=>typeof x.name==='string').slice(0,100)}catch{}
function save(){try{localStorage.setItem('delmar-list',JSON.stringify(list))}catch{$('#feedback').textContent='Não foi possível guardar neste dispositivo.'}renderList()}
function add(name){if(list.length>=100)return;list.push({id:crypto.randomUUID(),name:name.trim().slice(0,100),done:false});save();$('#feedback').textContent='Adicionado à sua lista.'}
function renderCategories(){const el=$('#categories');el.innerHTML=categories.filter(c=>filter==='Todas'||c[1]===filter).map(c=>`<article class="category"><div class="category-art"><svg viewBox="0 0 150 130" aria-hidden="true">${art[c[2]]}</svg></div><div class="category-bottom"><div><h3>${escapeHTML(c[0])}</h3><small>${escapeHTML(c[3])}</small></div><button aria-label="Adicionar ${escapeHTML(c[0])} à lista" data-add="${escapeHTML(c[0])}">+</button></div></article>`).join('');el.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add))}
function renderList(){$('#count').textContent=list.length;$('#list-total').textContent=`${list.length} ${list.length===1?'artigo':'artigos'}`;$('#empty-list').hidden=!!list.length;$('#shopping-items').innerHTML=list.map(x=>`<li class="${x.done?'done':''}"><label><input type="checkbox" data-check="${escapeHTML(x.id)}" ${x.done?'checked':''}><span>${escapeHTML(x.name)}</span></label><button aria-label="Retirar ${escapeHTML(x.name)}" data-remove="${escapeHTML(x.id)}">×</button></li>`).join('');document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{list.find(x=>x.id===b.dataset.check).done=b.checked;save()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{list=list.filter(x=>x.id!==b.dataset.remove);save()})}
$('.menu-toggle').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open)};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderCategories()});$('#list-form').onsubmit=e=>{e.preventDefault();if($('#item').value.trim())add($('#item').value);$('#item').value='';$('#item').focus()};$('#clear-list').onclick=()=>{list=[];save();$('#feedback').textContent='Lista limpa.'};$('#copy-list').onclick=async()=>{try{await navigator.clipboard.writeText('Lista Casa Delmar\n'+list.map(x=>(x.done?'✓ ':'☐ ')+x.name).join('\n'));$('#feedback').textContent='Lista copiada.'}catch{$('#feedback').textContent='Não foi possível copiar. Pode selecionar os artigos e copiar manualmente.'}};$('#memory-button').onclick=()=>$('#memory-dialog').showModal();$('.close-dialog').onclick=()=>$('#memory-dialog').close();$('#memory-dialog').onclick=e=>{if(e.target===$('#memory-dialog'))e.target.close()};renderCategories();renderList();
let catalog=[],search='',category='Todas',onlyOffers=false;
const euro=c=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(c/100);
function renderProducts(){const box=$('#products');if(!box)return;const items=catalog.filter(p=>(category==='Todas'||p.category===category)&&(!onlyOffers||p.offerActive)&&(`${p.name} ${p.description}`.toLocaleLowerCase('pt').includes(search)));box.innerHTML=items.length?items.map(p=>`<article class="product"><div class="product-picture">${p.image?`<img src="${escapeHTML(p.image)}" alt="${escapeHTML(p.name)}" loading="lazy">`:`<svg viewBox="0 0 150 130" aria-hidden="true">${art[p.art]||art.mercearia}</svg>`}${p.offerActive?'<span class="offer-tag">Em destaque</span>':''}</div><div class="product-info"><small>${escapeHTML(p.category)}${p.illustrative?' · Exemplo':''}</small><h3>${escapeHTML(p.name)}</h3><p>${escapeHTML(p.description)}</p><div class="product-price"><span>${p.priceCents===null?'Preço sob consulta':euro(p.offerActive?p.offerPriceCents:p.priceCents)}${p.offerActive?` <del>${euro(p.priceCents)}</del>`:''}<small>${escapeHTML(p.unit||'')}</small></span><button data-product="${escapeHTML(p.id)}" aria-label="Adicionar ${escapeHTML(p.name)} à lista">+</button></div>${p.offerActive?`<small>Até ${escapeHTML(p.offerEnd)} · Sujeito a disponibilidade</small>`:''}</div></article>`).join(''):'<p class="empty-products">Não encontrámos produtos com estes filtros. Experimente outra pesquisa.</p>';box.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>add(catalog.find(p=>p.id===b.dataset.product).name));$('#result-count').textContent=`${items.length} ${items.length===1?'produto':'produtos'}`}
async function loadCatalog(){try{const r=await fetch('/api/catalog');if(!r.ok)throw Error();const data=await r.json();catalog=data.products;applySettings(data.settings);if(data.settings.ordersEnabled)$('#request-area').hidden=false;}catch{const r=await fetch('/catalog.json');const data=await r.json();catalog=data.products;$('#catalog-state').textContent='Catálogo de demonstração · Produtos e disponibilidade por confirmar.';}const cats=[...new Set(catalog.map(p=>p.category))];$('#product-category').innerHTML='<option>Todas</option>'+cats.map(c=>`<option>${escapeHTML(c)}</option>`).join('');renderProducts()}
function applySettings(s){if(s.story)$('#story-managed').textContent=s.story;if(s.hours)$('#store-hours').textContent=s.hours;$('#catalog-state').textContent=s.demo?'Catálogo de demonstração · Produtos e disponibilidade por confirmar.':'Seleção da loja · Disponibilidade confirmada pelo Casa Delmar.';if(!s.demo)document.querySelector('.preview').hidden=true;if(s.flyerUrl){$('#flyer-link').href=s.flyerUrl;$('#flyer-link').hidden=false}if(s.name)document.title=s.name+' · Furadouro';if(s.privacyText)$('#privacy-text').textContent=s.privacyText;}
$('#product-search').oninput=e=>{search=e.target.value.trim().toLocaleLowerCase('pt');renderProducts()};$('#product-category').onchange=e=>{category=e.target.value;renderProducts()};$('#only-offers').onchange=e=>{onlyOffers=e.target.checked;renderProducts()};$('#request-form').onsubmit=async e=>{e.preventDefault();const status=$('#request-status'),button=e.target.querySelector('button');if(!list.length){status.textContent='Adicione primeiro artigos à lista.';return}button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.items=list.map(x=>x.name);data.consent=true;const r=await fetch('/api/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.error);status.textContent=`Pedido ${j.reference} recebido. Aguarde confirmação da loja. Não constitui uma compra.`;e.target.reset()}catch(err){status.textContent=err.message||'Não foi possível enviar. Contacte a loja por telefone.'}finally{button.disabled=false}};loadCatalog().catch(()=>{$('#catalog-state').textContent='Catálogo temporariamente indisponível. Contacte a loja.'});
